beforeExample:
public class MyClass {
    boolean isValid() {
        return true;
    }

    void test() {
        boolean x = true;
        boolean result1 = !!x;
        boolean result2 = !(!isValid());
        boolean result3 = !(!(!true)); // Example for iterative application
    }
}

afterExample:
public class MyClass {
    boolean isValid() {
        return true;
    }

    void test() {
        boolean x = true;
        boolean result1 = x;
        boolean result2 = isValid();
        boolean result3 = !true;
    }
}

negativeExample:
public class MyClass {
    boolean isValid() {
        return true;
    }

    void test() {
        boolean x = true;
        boolean result1 = !x;
        boolean result2 = !(isValid());
        boolean result3 = true; // Not a negation
    }
}
